const migrar=x=>{if(!x||typeof x!="object")return nuevo();const b=nuevo(),o=Object.assign(b,x);o.cfg=Object.assign(nuevo().cfg,x.cfg||{});if(o.cfg.k_min<K_MIN_PISO)o.cfg.k_min=K_MIN_PISO;o.v=1;return o};
S.hist=migrar(T.ls("hist",null));{const s0=T.save;T.save=()=>{s0();T.lsSet("hist",S.hist)}}
