HI.priorizar=()=>Object.entries(E.municipal.ASAM2023).map(([d,r])=>{const p=HI.participacion("ASAM2023",d),inv=r.votantes?((r.nulos||0)+(r.no_marcados||0))*100/r.votantes:null;
 return{dane:d,nombre:(DV.get(d)||{}).nombre,provincia:(DV.get(d)||{}).provincia,abst:p.disponible?100-p.participacion:null,inv,atipico:HI.atipico(2023,d),
  puntaje:(p.disponible?100-p.participacion:0)+2*(inv||0),accion:inv>=10?"Pedagogía del tarjetón (no marcados y nulos altos)":p.disponible&&100-p.participacion>=40?"Participación: encuestas anónimas y grupos focales":"Logística de puesto (equipo)"}}).sort((a,b)=>b.puntaje-a.puntaje);
const PERSONAL=/\d{6,}|@|\b(c[eé]dula|tel[eé]fono|celular)\b/i;HI.PERSONAL=PERSONAL;
HI.accion=({tipo,dane,fecha,nota})=>{if(!["encuesta_anonima","grupo_focal","pedagogia_tarjeton","logistica_equipo"].includes(tipo))throw new Error("Tipo no permitido");if(!DV.get(dane))throw new Error("Municipio");
 if(PERSONAL.test(nota||""))throw new Error("Sin datos personales: las acciones se registran en agregado (sin documentos, teléfonos ni correos)");const a={id:"AP-"+(S.hist.acciones.length+1),tipo,dane,fecha,nota:String(nota||"").trim()};S.hist.acciones.push(a);T.save();T.log("historico.participacion",a.id+" "+tipo+" "+dane);return a};
