HI.diaE=()=>{const out=[];(S.mesas||[]).forEach(m=>{const d=[...DV.values()].find(x=>nrm(x.nombre)==nrm(m.mun));const h=d?HI.participacion("ASAM2023",d.dane):{disponible:false};
 const tot=m.e14?m.e14.total:m.oficial.total,part=m.inscritos?tot*100/m.inscritos:null,dif=h.disponible&&part!=null?part-h.participacion:null;
 out.push({id:m.id,mun:m.mun,mesa:m.mesa,puesto:m.puesto,total:tot,fuente:m.e14?"E-14 del testigo":"preconteo (demo)",part,hist:h.disponible?h.participacion:null,dif,alerta:dif!=null&&Math.abs(dif)>15})});return out};
