 if(!(c.bastion_pct>0&&c.bastion_pct<100)||!(c.disputa_margen>=0&&c.disputa_margen<50)||!(c.cobertura_min>0&&c.cobertura_min<=100)||!(c.riesgo_min>=0&&c.riesgo_min<=1))throw new Error("Valores fuera de rango");
